// The client's view of a local directory: which files it holds, under which
// keys, with which contents.

import { createHash } from 'node:crypto';
import fs from 'node:fs';
import fsp from 'node:fs/promises';
import path from 'node:path';

// ignoreBOM keeps a leading U+FEFF, which is part of the name.
const utf8 = new TextDecoder('utf-8', { fatal: true, ignoreBOM: true });

/**
 * Lists the regular files under `root`, recursively, with their keys: the
 * path relative to `root` with "/" as the separator, the same convention the
 * server uses. Symbolic links and special files are not followed or read;
 * neither are names that are not valid UTF-8, which no key can express.
 * Each of those is reported through `onSkip` instead.
 *
 * @param {string} root
 * @param {{ onSkip?: (relPath: string, reason: string) => void }} [options]
 * @returns {Promise<Array<{ key: string, path: string }>>} sorted by key
 * @throws {Error} if `root` is not a readable directory
 */
export async function listFiles(root, { onSkip = () => {} } = {}) {
  const stat = await fsp.stat(root);
  if (!stat.isDirectory()) {
    const err = new Error(`not a directory: ${root}`);
    err.code = 'ENOTDIR';
    throw err;
  }
  const files = [];
  await walk(root, [], files, onSkip);
  return files.sort((a, b) => (a.key < b.key ? -1 : a.key > b.key ? 1 : 0));
}

async function walk(dir, prefix, out, onSkip) {
  // Names as raw bytes, so that one which is not valid UTF-8 is noticed
  // instead of silently becoming U+FFFD.
  const entries = await fsp.readdir(dir, { withFileTypes: true, encoding: 'buffer' });
  for (const entry of entries) {
    let name;
    try {
      name = utf8.decode(entry.name);
    } catch {
      onSkip([...prefix, entry.name.toString()].join('/'), 'file name is not valid UTF-8');
      continue;
    }
    const segments = [...prefix, name];
    const full = path.join(dir, name);
    if (entry.isDirectory()) {
      await walk(full, segments, out, onSkip);
    } else if (entry.isFile()) {
      out.push({ key: segments.join('/'), path: full });
    } else if (entry.isSymbolicLink()) {
      onSkip(segments.join('/'), 'symbolic link');
    } else {
      onSkip(segments.join('/'), 'not a regular file');
    }
  }
}

/**
 * Splits a key into the path segments of the file it names under the root,
 * the reverse of what listFiles() does.
 *
 * @param {string} key
 * @returns {string[] | null} null if the key is not a plain relative path
 *   (empty, absolute, an empty, "." or ".." segment, a NUL, a lone
 *   surrogate), i.e. names no file inside the root
 */
export function keySegments(key) {
  if (typeof key !== 'string' || !key.isWellFormed() || key.includes('\0')) {
    return null;
  }
  const segments = key.split('/');
  if (segments.some((s) => s === '' || s === '.' || s === '..')) {
    return null;
  }
  return segments;
}

/**
 * @param {string} file
 * @returns {Promise<string>} SHA-256 of the file's contents, in hex
 */
export async function sha256File(file) {
  const hash = createHash('sha256');
  for await (const chunk of fs.createReadStream(file)) {
    hash.update(chunk);
  }
  return hash.digest('hex');
}
import { listFiles, sha256File } from './local-files.js';

/**
 * Uploads every file under `dir` that the server lacks or holds with
 * different contents. Files whose SHA-256 matches the server's copy are not
 * sent again. Nothing is deleted on either side. Stops at the first failure.
 *
 * @param {{
 *   dir: string,
 *   client: import('./client.js').SyncboxClient,
 *   log?: (line: string) => void,   progress, one line per uploaded file
 *   warn?: (line: string) => void,  files left out
 * }} options
 * @returns {Promise<{ uploaded: string[], upToDate: string[] }>} keys
 */
export async function push({ dir, client, log = () => {}, warn = () => {} }) {
  const files = await listFiles(dir, {
    onSkip: (relPath, reason) => warn(`skipping ${relPath}: ${reason}`),
  });
  const remote = new Map((await client.list()).map((blob) => [blob.key, blob.sha256]));

  const uploaded = [];
  const upToDate = [];
  for (const { key, path } of files) {
    if (remote.get(key) === (await sha256File(path))) {
      upToDate.push(key);
      continue;
    }
    await client.put(key, path);
    uploaded.push(key);
    log(`uploaded ${key}`);
  }
  return { uploaded, upToDate };
}
import { randomBytes } from 'node:crypto';
import { createWriteStream } from 'node:fs';
import fs from 'node:fs/promises';
import path from 'node:path';

import { RequestError } from './client.js';
import { keySegments, sha256File } from './local-files.js';

/** A blob that cannot be written because of what is already in the directory. */
export class LocalConflictError extends Error {
  constructor(message) {
    super(message);
    this.name = 'LocalConflictError';
  }
}

/**
 * Downloads every blob that `dir` lacks or holds with different contents,
 * writing it to the relative path named by its key and creating missing
 * subdirectories (and `dir` itself). Files whose SHA-256 matches the
 * server's copy are not fetched again. Nothing is deleted on either side.
 * Stops at the first failure.
 *
 * Each file is written to a temporary file next to it and renamed into
 * place once complete and verified against the SHA-256 the server listed,
 * so an interrupted pull never leaves a truncated file behind.
 *
 * Nothing is written outside `dir`: keys that are not plain relative paths
 * are skipped, and so are paths that would lead through or onto a symbolic
 * link (push does not follow those either).
 *
 * @param {{
 *   dir: string,
 *   client: import('./client.js').SyncboxClient,
 *   log?: (line: string) => void,   progress, one line per downloaded file
 *   warn?: (line: string) => void,  blobs left out
 *   signal?: AbortSignal,           stops the pull, rejecting with an AbortError
 * }} options
 * @returns {Promise<{ downloaded: string[], upToDate: string[] }>} keys
 * @throws {LocalConflictError} if a blob's path is taken locally by
 *   something other than a regular file (e.g. a directory)
 */
export async function pull({ dir, client, log = () => {}, warn = () => {}, signal }) {
  await checkDirectory(dir);
  const blobs = (await client.list({ signal })).sort((a, b) => (a.key < b.key ? -1 : a.key > b.key ? 1 : 0));
  await fs.mkdir(dir, { recursive: true });

  const downloaded = [];
  const upToDate = [];
  for (const blob of blobs) {
    signal?.throwIfAborted();
    const segments = keySegments(blob.key);
    if (segments === null) {
      warn(`skipping ${JSON.stringify(blob.key)}: key is not a relative path inside the directory`);
      continue;
    }
    const target = await inspectTarget(dir, blob.key, segments);
    if (target.skip !== undefined) {
      warn(`skipping ${blob.key}: ${target.skip}`);
      continue;
    }
    if (target.mode !== undefined && (await sha256File(target.path)) === blob.sha256) {
      upToDate.push(blob.key);
      continue;
    }
    await download(client, blob, target, signal);
    downloaded.push(blob.key);
    log(`downloaded ${blob.key}`);
  }
  return { downloaded, upToDate };
}

/** `dir` may be missing (pull creates it), but if it exists it must be a directory. */
async function checkDirectory(dir) {
  let stat;
  try {
    stat = await fs.stat(dir);
  } catch (err) {
    if (err.code === 'ENOENT') {
      return;
    }
    throw err;
  }
  if (!stat.isDirectory()) {
    const err = new Error(`not a directory: ${dir}`);
    err.code = 'ENOTDIR';
    throw err;
  }
}

/**
 * Looks at what is at a key's path in `dir` now, without following symbolic
 * links anywhere below `dir`. Only reads; status relies on that too.
 *
 * @param {string} dir
 * @param {string} key
 * @param {string[]} segments  of the key, from keySegments()
 * @returns {Promise<{ path: string, mode?: number, skip?: string }>}
 *   `mode` is set if a regular file is there; `skip` says why the blob
 *   must be left alone
 * @throws {LocalConflictError} if a directory is at the key's path, or
 *   something other than a directory where one of its parents should be
 */
export async function inspectTarget(dir, key, segments) {
  let current = dir;
  for (let i = 0; i < segments.length; i++) {
    current = path.join(current, segments[i]);
    const isLast = i === segments.length - 1;
    const where = segments.slice(0, i + 1).join('/');
    let stat;
    try {
      stat = await fs.lstat(current);
    } catch (err) {
      if (err.code === 'ENOENT') {
        break;
      }
      throw err;
    }
    if (stat.isSymbolicLink()) {
      return { skip: isLast ? 'symbolic link' : `${where} is a symbolic link` };
    }
    if (isLast) {
      if (stat.isDirectory()) {
        throw new LocalConflictError(`cannot write ${key}: a directory is in the way`);
      }
      if (!stat.isFile()) {
        return { skip: 'not a regular file' };
      }
      return { path: current, mode: stat.mode & 0o7777 };
    }
    if (!stat.isDirectory()) {
      throw new LocalConflictError(`cannot write ${key}: ${where} is not a directory`);
    }
  }
  return { path: path.join(dir, ...segments) };
}

async function download(client, blob, target, signal) {
  const parent = path.dirname(target.path);
  await fs.mkdir(parent, { recursive: true });
  const temp = path.join(parent, `.syncbox-${randomBytes(8).toString('hex')}.part`);
  // flush: fsync before closing, so that the renamed file has its contents
  // on disk even if the machine goes down right after.
  const output = createWriteStream(temp, { flags: 'wx', flush: true });
  try {
    const received = await client.download(blob.key, output, { signal });
    if (received.sha256 !== blob.sha256) {
      throw new RequestError(
        `GET ${blob.key}: the downloaded contents do not match the SHA-256 listed by the server ` +
          '(was the blob changed during the pull?)',
      );
    }
    if (target.mode !== undefined) {
      // Replacing a file keeps its permissions.
      await fs.chmod(temp, target.mode);
    }
    await fs.rename(temp, target.path);
  } catch (err) {
    // Still open if the server refused before sending any content. Waiting
    // for the close also waits for the open, which creates the file.
    if (!output.closed) {
      await new Promise((resolve) => output.once('close', resolve).destroy());
    }
    await fs.rm(temp, { force: true });
    throw err;
  }
}

